// Valide AVANT d'écrire : un dépôt incomplet vaut mieux refusé qu'accepté à vide.
// Le job passera en failed côté worker (invariant « completed ⟹ texte », #418).
const input = $input.first().json;
const body = input.body || input;

const jobId = body.job_id;
const result = body.result;

if (!jobId || typeof jobId !== 'string') {
  return [{ json: { valide: false, erreur: 'job_id requis (chaîne)' } }];
}
if (!result || typeof result !== 'object') {
  return [{ json: { valide: false, erreur: 'result requis (objet)' } }];
}

// Le TTL court à partir d'ICI — donc de la fin du job, pas du dispatch.
const TTL_SECONDES = 3600;

return [{
  json: {
    valide: true,
    jobId: jobId,
    cle: `job:document:${jobId}`,
    ttl: TTL_SECONDES,
    charge: JSON.stringify({
      job_id: jobId,
      result: result,
      stored_at: new Date().toISOString(),
      ttl_seconds: TTL_SECONDES
    })
  }
}];

// Le job_id arrive en query. Pas de valeur par défaut : lire une clé arbitraire
// renverrait le résultat d'un autre utilisateur.
const input = $input.first().json;
const query = input.query || {};
const jobId = query.job_id;

if (!jobId || typeof jobId !== 'string') {
  return [{ json: { valide: false, erreur: 'job_id requis en paramètre' } }];
}

return [{ json: { valide: true, jobId: jobId, cle: `job:document:${jobId}` } }];

// Distingue TROIS cas, que le consommateur doit pouvoir séparer :
//   found:true             → le texte est là
//   found:false, expired   → la clé a vécu puis expiré (fenêtre TTL dépassée)
//   found:false            → jamais stockée (job échoué avant le dépôt)
// Sans cette distinction, desktop ne peut pas décider entre « re-poller »,
// « re-dispatcher » et « signaler une erreur ».
const jobId = $('Lire Paramètres').first().json.jobId;
const brut = $input.first().json;

// Le node Redis renvoie la valeur sous la clé demandée, ou propertyName
const valeur = brut[`job:document:${jobId}`] ?? brut.propertyName ?? brut.value ?? null;

if (!valeur) {
  return [{
    json: {
      success: true,
      found: false,
      job_id: jobId,
      reason: 'absent_ou_expire',
      message: 'Aucun résultat pour ce job : jamais stocké, ou fenêtre de 1 h dépassée.'
    }
  }];
}

let charge;
try {
  charge = typeof valeur === 'string' ? JSON.parse(valeur) : valeur;
} catch (e) {
  return [{
    json: {
      success: false,
      found: false,
      job_id: jobId,
      error: 'contenu illisible en base',
      error_code: 'CORRUPT_PAYLOAD'
    }
  }];
}

return [{
  json: {
    success: true,
    found: true,
    job_id: jobId,
    stored_at: charge.stored_at,
    result: charge.result
  }
}];
